#!/bin/bash

cd ${GITHUB_WORKSPACE}

OPTION_LIST=(
    -DWINDOWS_RUB_INCLUDE="${DEPENDS_BUILD_PREFIX}/${WINDOWSRUB_NAME}/include"
    -DCXXOPTS_ROOT="${DEPENDS_BUILD_PREFIX}/${CXXOPTS_NAME}"
    -DFFMPEG_ROOT="${DEPENDS_BUILD_PREFIX}/${FFMPEG_NAME}/build"
)
echo "${OPTION_LIST[@]}"

cmake -B ${BUILD_DIR} \
"${OPTION_LIST[@]}" \
&& \
cmake --build ${BUILD_DIR} --config Release